package game.sanguo.core;
import java.nio.file.*;import java.util.*;
class session_b_inspect_sworn_checkpoint {
 public static void main(String[]args)throws Exception {
  byte[] raw=Files.readAllBytes(Path.of(args[0]));World w=SaveCodec.decode(raw);boolean beforePure=Arrays.equals(raw,SaveCodec.encode(w));if(args.length>1&&args[1].equals("--turn"))System.err.println("Actual full turn result "+w.nextTurn().ok);var facts=PcDuelSourceFacts.saved(w);var rows=new ArrayList<Object>();for(int nativeId:new int[]{355,365,377,614,624,635,98,432}){var f=facts.values().stream().filter(x->x.nativeId==nativeId).findFirst().orElseThrow();var o=w.officer(f.officerId);rows.add(MapJson.obj("nativeId",nativeId,"id",o.id,"name",o.name,"owner",o.owner,"role",o.role.name(),"life",w.life.state(o.id).name(),"unit",o.unitId,"city",o.cityId,"task",o.otherTask,"taskTurns",o.otherTaskTurns,"acted",o.acted,"captive",w.government.captive(o.id),"war",o.war));}var units=new ArrayList<Object>();for(var u:w.units)units.add(MapJson.obj("unit",u.id,"native",facts.containsKey(u.officerId)?facts.get(u.officerId).nativeId:-1,"owner",u.owner,"hex",u.hex.toString(),"acted",u.acted,"troops",u.troops));var governors=new ArrayList<Object>();var data=PcGovernorPolicy.data(w);for(var c:w.cities)if(c.governorId>=0){var o=w.officer(c.governorId);var a=data.assignments.get(c.governorId);governors.add(MapJson.obj("city",c.id,"siteNative",data.source.sites.get(c.id).nativeId,"cityOwner",c.owner,"id",o.id,"native",facts.get(o.id).nativeId,"name",o.name,"owner",o.owner,"role",o.role.name(),"cityOfOfficer",o.cityId,"unit",o.unitId,"homeNative",a.home,"army",a.army,"task",o.otherTask,"turns",o.otherTaskTurns,"captive",w.government.captive(o.id),"positionValid",o.owner==c.owner&&o.cityId==c.id&&o.unitId==-1,"verifiedDeployedRuler",PcGovernorPolicy.deployedRulerGovernor(w,o,c)));}String saveError="";boolean afterPure=false;try{afterPure=Arrays.equals(raw,SaveCodec.encode(w));}catch(Exception e){saveError=e.toString();}System.out.println(new String(MapJson.bytes(MapJson.obj("turn",w.turn,"player",w.player,"active",w.active,"people",rows,"units",units,"readPureBefore",beforePure,"readPure",afterPure,"postSaveError",saveError,"governors",governors))));
 }
}
